&lt;h2 class=&quot;separator&quot;&gt;Les comp&#233;tences&lt;a class=&quot;headeranchor&quot; id=&quot;Les_comp&#233;tences_0&quot; href=&quot;#Les_comp&#233;tences_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;
